def main():
    for relpath, b64content in FILES.items():
        data = base64.b64decode(b64content.strip())
        os.makedirs(os.path.dirname(relpath), exist_ok=True) if os.path.dirname(relpath) else None
        with open(relpath, "wb") as f:
            f.write(data)
        print(f"Escrito: {relpath} ({len(data)} bytes)")
    print()
    print("Listo. Revisa 'git diff', ejecuta 'npx prisma db push' en backend/,")
    print("aplica backend/prisma/migrations-manual/fase23-migrar-roles-legacy.sql")
    print("contra tu base de datos, y reinicia el backend antes de probar.")

if __name__ == "__main__":
    main()
